package de.fitnesscoach.domain.plan;
import java.time.*;import java.util.*;import de.fitnesscoach.data.entity.*;import de.fitnesscoach.data.repository.FitnessCoachRepository;
public final class TrainingPlanService{private final FitnessCoachRepository repo;private final TrainingPlanGenerator generator=new TrainingPlanGenerator();private final WorkoutMatcher matcher=new WorkoutMatcher();private final PlanAdaptationPolicy adaptation=new DefaultPlanAdaptationPolicy();public TrainingPlanService(FitnessCoachRepository r){repo=r;}public TrainingPlanGenerator.Result ensureWeek(LocalDate week){List<PlannedWorkoutEntity>existing=repo.getPlannedWorkouts(week,week.plusDays(6));if(!existing.isEmpty())return new TrainingPlanGenerator.Result(existing,DomainEnums.Confidence.MEDIUM);TrainingPlanGenerator.Result x=generator.generate(week,repo.getProfile(),repo.getActiveGoal(),repo.getAvailability(),repo.getBaseline("trainingLoad",28));for(PlannedWorkoutEntity p:x.workouts){long id=repo.insertPlannedWorkout(p);audit(DomainEnums.CoachDecisionType.CREATE_WORKOUT,id,null,snapshot(p),"INITIAL_PLAN","Deterministic weekly plan generation");}return x;}public WorkoutMatcher.Match match(WorkoutEntity actual,List<PlannedWorkoutEntity>week){WorkoutMatcher.Match m=matcher.best(actual,week);if(m.planned!=null&&m.confidence==WorkoutMatcher.MatchConfidence.HIGH){actual.plannedWorkoutId=m.planned.id;actual.status=DomainEnums.WorkoutStatus.COMPLETED;repo.updateWorkout(actual);m.planned.status=DomainEnums.WorkoutStatus.COMPLETED;m.planned.originalWorkoutId=actual.id;m.planned.updatedAt=Instant.now();repo.updatePlannedWorkout(m.planned);audit(DomainEnums.CoachDecisionType.REPLACE_WORKOUT,m.planned.id,"unmatched",snapshot(m.planned),"AUTO_MATCH","Imported workout matched with HIGH confidence");}return m;}public PlannedWorkoutEntity adapt(LocalDate date){List<PlannedWorkoutEntity>w=repo.getPlannedWorkouts(date.minusDays(1),date.plusDays(1));PlannedWorkoutEntity cur=null,prev=null,next=null;for(PlannedWorkoutEntity p:w){if(p.date.equals(date))cur=p;else if(p.date.isBefore(date))prev=p;else next=p;}if(cur==null)return null;RecoveryEntity r=repo.getRecovery(date);DomainEnums.RecoveryRecommendation rec=r==null?DomainEnums.RecoveryRecommendation.UNKNOWN:r.recommendation;String before=snapshot(cur);PlannedWorkoutEntity changed=adaptation.adapt(cur,rec,prev,next);if(changed.status==DomainEnums.WorkoutStatus.ADAPTED){repo.updatePlannedWorkout(changed);audit(decision(cur,changed),changed.id,before,snapshot(changed),"RECOVERY_"+rec,"Deterministic recovery adaptation; missed workouts are not moved automatically");}return changed;}private DomainEnums.CoachDecisionType decision(PlannedWorkoutEntity a,PlannedWorkoutEntity b){if(b.workoutType==DomainEnums.WorkoutType.REST)return DomainEnums.CoachDecisionType.CANCEL_WORKOUT;return DomainEnums.CoachDecisionType.REDUCE_WORKOUT;}private void audit(DomainEnums.CoachDecisionType t,long id,String before,String after,String code,String reason){CoachDecisionEntity d=new CoachDecisionEntity();d.timestamp=Instant.now();d.decisionType=t;d.targetEntityId=id;d.beforeJson=before;d.afterJson=after;d.reasonCode=code;d.reasonText=reason;d.source="DETERMINISTIC_PLAN_ENGINE";repo.insertDecision(d);}private String snapshot(PlannedWorkoutEntity p){return p==null?null:"{date:"+p.date+",type:"+p.workoutType+",duration:"+p.plannedDurationMinutes+",status:"+p.status+",version:"+p.version+"}";}}
